      <?php if($canManage):?><details class="permission-editor"><summary>Rolle, Rechte & Serverfreigaben bearbeiten</summary><form method="post" action="/users/<?=$uid?>" class="form-stack top-gap-small"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><div class="form-grid"><label>Webpanel-Rolle<select name="web_role"><?php foreach(Auth::WEB_ROLES as $r=>$label):if($r!==$webRole&&!Auth::canAssignWebRole($r))continue;?><option value="<?=Security::e($r)?>" <?=$r===$webRole?'selected':''?>><?=Security::e($label)?></option><?php endforeach;?></select></label><label class="checkbox-line"><input type="checkbox" name="active" value="1" <?=$u['active']?'checked':''?>> Konto aktiv</label></div>
        <?php if($canPermissions&&$webRole!=='founder'):?><details class="nested-permission-editor" open><summary>Individuelle Rechte</summary><div class="permission-editor-toolbar"><input type="search" placeholder="Recht suchen …" data-permission-search><label class="checkbox-line"><input type="checkbox" data-permission-only-overrides> Nur Abweichungen</label></div><p class="small-muted">Vorlage = folgt automatisch der Rolle. „Verbieten“ gewinnt auch dann, wenn ein Paket oder die Vorlage das Recht erlaubt.</p><?php foreach($permissionGroups as $group=>$prefixes):?><fieldset class="permission-fieldset"><legend><?=Security::e($group)?></legend><div class="permission-override-grid"><?php foreach(Auth::PERMISSIONS as $permission=>$label):if(permissionGroup179($permission,$permissionGroups)!==$group)continue;$encoded=str_replace('.','__',$permission);$mode=array_key_exists($permission,$overrides)?($overrides[$permission]?'allow':'deny'):'inherit';$canGrant=Auth::isFounder()||Auth::can($permission);$danger=Auth::isDangerousPermission($permission);?><label class="permission-override-row <?=$danger?'is-dangerous':''?>" data-permission-item data-permission-text="<?=Security::e(strtolower($label.' '.$permission))?>" data-override="<?=$mode==='inherit'?'0':'1'?>"><span><?=Security::e($label)?><?php if($danger):?><em>Kritisch</em><?php endif;?><small><?=Security::e($permission)?></small></span><select name="perm_override[<?=Security::e($encoded)?>]"><option value="inherit" <?=$mode==='inherit'?'selected':''?>>Vorlage (<?=$effective[$permission]?'AN':'AUS'?>)</option><?php if($canGrant):?><option value="allow" <?=$mode==='allow'?'selected':''?>>Ausdrücklich erlauben</option><?php endif;?><option value="deny" <?=$mode==='deny'?'selected':''?>>Ausdrücklich verbieten</option></select></label><?php endforeach;?></div></fieldset><?php endforeach;?></details>
        <details class="nested-permission-editor"><summary>Direkte Serverabweichungen</summary><p class="small-muted">Direkte Serverfreigaben und Servergruppen sind explizite Abweichungen; ein Verbot gewinnt bei Konflikten. Ein Ablaufdatum macht die Abweichung automatisch temporär.</p><div class="server-access-grid"><?php foreach($servers as $server):$sid=(int)$server['id'];$row=$accessForUser[$sid]??null;?><article class="server-access-card"><strong><?=Security::e($server['name'])?></strong><label>Modus<select name="server_mode[<?=$sid?>]"><option value="inherit" <?=$row?'':'selected'?>>Rollenvorlage/Servergruppe verwenden</option><option value="custom" <?=$row?'selected':''?>>Individuell</option></select></label><div class="permission-check-grid compact"><?php foreach($capLabels as $cap=>$label):$column=['view'=>'can_view','players'=>'can_manage_players','permissions'=>'can_manage_permissions','sync'=>'can_sync','live'=>'can_live_admin'][$cap];?><label class="permission-check"><input type="checkbox" name="server_cap[<?=$sid?>][<?=Security::e($cap)?>]" value="1" <?=($row&&(int)$row[$column]===1)?'checked':''?>> <span><?=Security::e($label)?></span></label><?php endforeach;?></div><label>Max. CS2-Rolle<select name="server_max_game_role[<?=$sid?>]"><?php $currentMax=$row['max_game_role']??Auth::roleTemplate($webRole)['max_game_role'];foreach(Auth::GAME_ROLE_LEVELS as $gr=>$level):$actorMax=Auth::GAME_ROLE_LEVELS[Auth::serverMaxGameRole($sid)]??1;if(!Auth::isFounder()&&$level>$actorMax)continue;?><option value="<?=Security::e($gr)?>" <?=$currentMax===$gr?'selected':''?>><?=Security::e(ucfirst($gr))?></option><?php endforeach;?></select></label><label>Ablauf optional<input type="datetime-local" name="server_expires_at[<?=$sid?>]" value="<?=Security::e(htmlDate179($row['expires_at']??null))?>"></label></article><?php endforeach;?></div></details>
        <?php endif;?><label>Änderungsgrund<input type="text" name="change_reason" maxlength="240" placeholder="Erforderlich bei Rolle/Rechten/Status" required></label><button class="btn btn-primary">Benutzerrechte speichern</button></form></details><?php elseif($isMe):?><div class="small-muted">Die eigene Rolle und Rechte können nicht selbst erhöht/verändert werden.</div><?php else:?><div class="small-muted">Gleiche oder höhere Rollen sind durch die Ranghierarchie geschützt.</div><?php endif;?>

      <?php if($canManage&&Auth::can('roles.packages.manage')):?><details class="permission-editor"><summary>Rechtepakete</summary><div class="assignment-list"><?php foreach($packagesForUser as $a):?><div class="assignment-row"><span><strong><?=Security::e($a['package_name'])?></strong><small><?=Security::e($a['expires_at']?'bis '.$a['expires_at']:'ohne Ablauf')?> · <?=Security::e($a['reason']??'')?></small></span><form method="post" action="/users/<?=$uid?>/permission-package/<?=(int)$a['id']?>/remove"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><button class="btn btn-secondary btn-small">Entfernen</button></form></div><?php endforeach;?><?php if(!$packagesForUser):?><div class="small-muted">Keine Rechtepakete zugewiesen.</div><?php endif;?></div><form method="post" action="/users/<?=$uid?>/permission-package" class="form-grid top-gap-small"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><label>Paket<select name="package_id"><?php foreach($permissionPackages as $p):if(!$p['active'])continue;?><option value="<?=(int)$p['id']?>"><?=Security::e($p['name'])?></option><?php endforeach;?></select></label><label>Ablauf optional<input type="datetime-local" name="expires_at"></label><label>Grund<input name="reason" required maxlength="240"></label><button class="btn btn-primary">Zuweisen</button></form></details><?php endif;?>

      <?php if($canPermissions):?><details class="permission-editor"><summary>Temporäre Einzelrechte</summary><div class="assignment-list"><?php foreach($tempsForUser as $t):$expired=!empty($t['expires_at'])&&strtotime($t['expires_at'])<=time();?><div class="assignment-row <?=$expired?'is-expired':''?>"><span><strong><?=$t['effect']==='deny'?'VERBOT':'ERLAUBT'?> · <?=Security::e(Auth::PERMISSIONS[$t['permission_key']]??$t['permission_key'])?></strong><small><?=Security::e($t['expires_at']?'bis '.$t['expires_at']:'ohne Ablauf')?> · <?=Security::e($t['reason']??'')?><?=$expired?' · abgelaufen':''?></small></span><form method="post" action="/users/<?=$uid?>/temporary-permission/<?=(int)$t['id']?>/remove"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><button class="btn btn-secondary btn-small">Entfernen</button></form></div><?php endforeach;?><?php if(!$tempsForUser):?><div class="small-muted">Keine temporären Einzelrechte.</div><?php endif;?></div><form method="post" action="/users/<?=$uid?>/temporary-permission" class="form-grid top-gap-small"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><label>Recht<select name="permission_key"><?php foreach(Auth::PERMISSIONS as $perm=>$label):if(!Auth::isFounder()&&!Auth::can($perm))continue;?><option value="<?=Security::e($perm)?>"><?=Security::e($label)?></option><?php endforeach;?></select></label><label>Wirkung<select name="effect"><option value="allow">Temporär erlauben</option><option value="deny">Temporär verbieten</option></select></label><label>Ablauf<input type="datetime-local" name="expires_at" required></label><label>Grund<input name="reason" required maxlength="240"></label><button class="btn btn-primary">Temporäres Recht hinzufügen</button></form></details>

      <?php if($serverGroups):?><details class="permission-editor"><summary>Servergruppen-Zugriffe</summary><div class="assignment-list"><?php foreach($groupsForUser as $ga):?><div class="assignment-row"><span><strong><?=Security::e($ga['group_name'])?></strong><small><?=Security::e($ga['expires_at']?'bis '.$ga['expires_at']:'ohne Ablauf')?> · <?=Security::e($ga['reason']??'')?></small></span><form method="post" action="/users/<?=$uid?>/server-group/<?=(int)$ga['group_id']?>/remove"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><button class="btn btn-secondary btn-small">Entfernen</button></form></div><?php endforeach;?><?php if(!$groupsForUser):?><div class="small-muted">Keine Servergruppen zugewiesen.</div><?php endif;?></div><form method="post" action="/users/<?=$uid?>/server-group" class="form-stack top-gap-small"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><div class="form-grid"><label>Servergruppe<select name="group_id"><?php foreach($serverGroups as $g):?><option value="<?=(int)$g['id']?>"><?=Security::e($g['name'])?></option><?php endforeach;?></select></label><label>Max. CS2-Rolle<select name="max_game_role"><?php foreach(Auth::GAME_ROLE_LEVELS as $gr=>$level):?><option value="<?=Security::e($gr)?>"><?=Security::e(ucfirst($gr))?></option><?php endforeach;?></select></label><label>Ablauf optional<input type="datetime-local" name="expires_at"></label><label>Grund<input name="reason" required maxlength="240"></label></div><div class="permission-check-grid"><?php foreach($capLabels as $cap=>$label):?><label class="permission-check"><input type="checkbox" name="server_cap[<?=Security::e($cap)?>]" value="1"> <span><?=Security::e($label)?></span></label><?php endforeach;?></div><button class="btn btn-primary">Servergruppe zuweisen</button></form></details><?php endif;?>
      <?php endif;?>
    </article>
  <?php endforeach;?>
  </div>
</section>
</div>
